1	//! Kimi-K2.6 text-only constants, config probing, and derived shapes.
2	
3	// Most consumers live behind the kimi-k2 feature; the constants and shape
4	// helpers are intentionally kept compiling in feature-off builds.
5	#![cfg_attr(not(feature = "kimi-k2"), allow(dead_code))]
6	
7	use anyhow::Context;
8	use anyhow::Result;
9	use anyhow::bail;
10	use anyhow::ensure;
11	use serde_json::Value;
12	
13	pub(crate) const KIMI_K2_HIDDEN: usize = 7168;
14	pub(crate) const KIMI_K2_VOCAB: usize = 163_840;
15	pub const KIMI_K2_LAYERS: usize = 61;
16	pub(crate) const KIMI_K2_DENSE_LAYERS: usize = 1;
17	pub(crate) const KIMI_K2_MOE_LAYERS: usize = 60;
18	const KIMI_K2_MAX_CONTEXT: usize = 262_144;
19	
20	pub(crate) const KIMI_K2_HEADS: usize = 64;
21	pub(crate) const KIMI_K2_Q_LORA_RANK: usize = 1536;
22	const KIMI_K2_KV_LORA_RANK: usize = 512;
23	pub(crate) const KIMI_K2_QK_NOPE_HEAD_DIM: usize = 128;
24	pub(crate) const KIMI_K2_QK_ROPE_HEAD_DIM: usize = 64;
25	pub(crate) const KIMI_K2_Q_HEAD_DIM: usize = KIMI_K2_QK_NOPE_HEAD_DIM + KIMI_K2_QK_ROPE_HEAD_DIM;
26	pub(crate) const KIMI_K2_V_HEAD_DIM: usize = 128;
27	
28	pub(crate) const KIMI_K2_DENSE_INTERMEDIATE: usize = 18_432;
29	pub(crate) const KIMI_K2_EXPERT_INTERMEDIATE: usize = 2048;
30	pub(crate) const KIMI_K2_ROUTED_EXPERTS: usize = 384;
31	pub(crate) const KIMI_K2_TOPK: usize = 8;
32	const KIMI_K2_SHARED_EXPERTS: usize = 1;
33	pub(crate) const KIMI_K2_INT4_GROUP_SIZE: usize = 32;
34	
35	pub(crate) const KIMI_K2_ROPE_THETA: f32 = 50_000.0;
36	pub(crate) const KIMI_K2_YARN_FACTOR: f32 = 64.0;
37	pub(crate) const KIMI_K2_YARN_ORIGINAL_MAX_POS: usize = 4096;
38	pub(crate) const KIMI_K2_YARN_BETA_FAST: f32 = 32.0;
39	pub(crate) const KIMI_K2_YARN_BETA_SLOW: f32 = 1.0;
40	const KIMI_K2_ROUTED_SCALING_FACTOR: f32 = 2.827;
41	pub(crate) const KIMI_K2_RMS_NORM_EPS: f32 = 1.0e-5;
42	
43	/// Validate that `json` is a Kimi-K2.6 text config and that every dimension
44	/// matches the constants this crate is compiled against. This is a pure gate:
45	/// callers only care whether it succeeds, so nothing is materialized.
46	pub(crate) fn probe_config_json(json: &Value) -> Result<()> {
47	    let outer_model_type = string_field(json, "model_type")?;
48	    let text = if outer_model_type == "kimi_k25" {
49	        json.get("text_config")
50	            .ok_or_else(|| anyhow::anyhow!("Kimi outer config missing text_config"))?
51	    } else if outer_model_type == "kimi_k2" {
52	        json
53	    } else {
54	        bail!("not a Kimi-K2 config: model_type={outer_model_type}");
55	    };
56	
57	    let text_model_type = string_field(text, "model_type")?;
58	    ensure!(
59	        text_model_type == "kimi_k2",
60	        "Kimi text_config.model_type must be kimi_k2, got {text_model_type}"
61	    );
62	
63	    let hidden_size = usize_field(text, "hidden_size")?;
64	    let vocab_size = usize_field(text, "vocab_size")?;
65	    let num_hidden_layers = usize_field(text, "num_hidden_layers")?;
66	    let first_k_dense_replace = usize_field(text, "first_k_dense_replace")?;
67	    let max_position_embeddings = usize_field(text, "max_position_embeddings")?;
68	    let num_attention_heads = usize_field(text, "num_attention_heads")?;
69	    let q_lora_rank = usize_field(text, "q_lora_rank")?;
70	    let kv_lora_rank = usize_field(text, "kv_lora_rank")?;
71	    let qk_nope_head_dim = usize_field(text, "qk_nope_head_dim")?;
72	    let qk_rope_head_dim = usize_field(text, "qk_rope_head_dim")?;
73	    let v_head_dim = usize_field(text, "v_head_dim")?;
74	    let n_routed_experts = usize_field(text, "n_routed_experts")?;
75	    let num_experts_per_tok = usize_field(text, "num_experts_per_tok")?;
76	    let n_shared_experts = usize_field(text, "n_shared_experts")?;
77	    let moe_intermediate_size = usize_field(text, "moe_intermediate_size")?;
78	    let dense_intermediate_size = usize_field(text, "intermediate_size")?;
79	    let routed_scaling_factor = number_field(text, "routed_scaling_factor")?;
80	    let rms_norm_eps = number_field(text, "rms_norm_eps")?;
81	    let rope_theta = number_field(text, "rope_theta")?;
82	    ensure_float_close(
83	        routed_scaling_factor,
84	        f64::from(KIMI_K2_ROUTED_SCALING_FACTOR),
85	        1.0e-6,
86	        "routed_scaling_factor",
87	    )?;
88	    ensure_float_close(
89	        rope_theta,
90	        f64::from(KIMI_K2_ROPE_THETA),
91	        1.0e-6,
92	        "rope_theta",
93	    )?;
94	    ensure!(
95	        string_field(text, "topk_method")? == "noaux_tc",
96	        "Kimi topk_method must be noaux_tc"
97	    );
98	    ensure!(
99	        string_field(text, "scoring_func")? == "sigmoid",
100	        "Kimi scoring_func must be sigmoid"
101	    );
102	    ensure!(
103	        bool_field(text, "norm_topk_prob")?,
104	        "Kimi norm_topk_prob must be true"
105	    );
106	    ensure!(usize_field(text, "n_group")? == 1, "Kimi n_group must be 1");
107	    ensure!(
108	        usize_field(text, "topk_group")? == 1,
109	        "Kimi topk_group must be 1"
110	    );
111	
112	    ensure!(
113	        hidden_size == KIMI_K2_HIDDEN,
114	        "hidden_size mismatch: {hidden_size}"
115	    );
116	    ensure!(
117	        vocab_size == KIMI_K2_VOCAB,
118	        "vocab_size mismatch: {vocab_size}"
119	    );
120	    ensure!(
121	        num_hidden_layers == KIMI_K2_LAYERS,
122	        "num_hidden_layers mismatch: {num_hidden_layers}"
123	    );
124	    ensure!(
125	        first_k_dense_replace == KIMI_K2_DENSE_LAYERS,
126	        "first_k_dense_replace mismatch: {first_k_dense_replace}"
127	    );
128	    ensure!(
129	        max_position_embeddings == KIMI_K2_MAX_CONTEXT,
130	        "max_position_embeddings mismatch: {max_position_embeddings}"
131	    );
132	    ensure!(
133	        num_attention_heads == KIMI_K2_HEADS,
134	        "num_attention_heads mismatch: {num_attention_heads}"
135	    );
136	    ensure!(
