43	/// Validate that `json` is a Kimi-K2.6 text config and that every dimension
44	/// matches the constants this crate is compiled against. This is a pure gate:
45	/// callers only care whether it succeeds, so nothing is materialized.
46	pub(crate) fn probe_config_json(json: &Value) -> Result<()> {
47	    let outer_model_type = string_field(json, "model_type")?;
48	    let text = if outer_model_type == "kimi_k25" {
49	        json.get("text_config")
50	            .ok_or_else(|| anyhow::anyhow!("Kimi outer config missing text_config"))?
51	    } else if outer_model_type == "kimi_k2" {
52	        json
53	    } else {
54	        bail!("not a Kimi-K2 config: model_type={outer_model_type}");
55	    };
56	
57	    let text_model_type = string_field(text, "model_type")?;
58	    ensure!(
59	        text_model_type == "kimi_k2",
60	        "Kimi text_config.model_type must be kimi_k2, got {text_model_type}"
61	    );
62	
63	    let hidden_size = usize_field(text, "hidden_size")?;
64	    let vocab_size = usize_field(text, "vocab_size")?;
65	    let num_hidden_layers = usize_field(text, "num_hidden_layers")?;
66	    let first_k_dense_replace = usize_field(text, "first_k_dense_replace")?;
67	    let max_position_embeddings = usize_field(text, "max_position_embeddings")?;
68	    let num_attention_heads = usize_field(text, "num_attention_heads")?;
69	    let q_lora_rank = usize_field(text, "q_lora_rank")?;
70	    let kv_lora_rank = usize_field(text, "kv_lora_rank")?;
71	    let qk_nope_head_dim = usize_field(text, "qk_nope_head_dim")?;
72	    let qk_rope_head_dim = usize_field(text, "qk_rope_head_dim")?;
73	    let v_head_dim = usize_field(text, "v_head_dim")?;
74	    let n_routed_experts = usize_field(text, "n_routed_experts")?;
75	    let num_experts_per_tok = usize_field(text, "num_experts_per_tok")?;
76	    let n_shared_experts = usize_field(text, "n_shared_experts")?;
77	    let moe_intermediate_size = usize_field(text, "moe_intermediate_size")?;
78	    let dense_intermediate_size = usize_field(text, "intermediate_size")?;
79	    let routed_scaling_factor = number_field(text, "routed_scaling_factor")?;
80	    let rms_norm_eps = number_field(text, "rms_norm_eps")?;
81	    let rope_theta = number_field(text, "rope_theta")?;
82	    ensure_float_close(
83	        routed_scaling_factor,
84	        f64::from(KIMI_K2_ROUTED_SCALING_FACTOR),
85	        1.0e-6,
86	        "routed_scaling_factor",
87	    )?;
88	    ensure_float_close(
89	        rope_theta,
90	        f64::from(KIMI_K2_ROPE_THETA),
91	        1.0e-6,
92	        "rope_theta",
93	    )?;
94	    ensure!(
95	        string_field(text, "topk_method")? == "noaux_tc",
96	        "Kimi topk_method must be noaux_tc"
97	    );
98	    ensure!(
99	        string_field(text, "scoring_func")? == "sigmoid",
100	        "Kimi scoring_func must be sigmoid"
101	    );
102	    ensure!(
103	        bool_field(text, "norm_topk_prob")?,
104	        "Kimi norm_topk_prob must be true"
105	    );
106	    ensure!(usize_field(text, "n_group")? == 1, "Kimi n_group must be 1");
107	    ensure!(
108	        usize_field(text, "topk_group")? == 1,
109	        "Kimi topk_group must be 1"
110	    );
111	
112	    ensure!(
113	        hidden_size == KIMI_K2_HIDDEN,
114	        "hidden_size mismatch: {hidden_size}"
115	    );
116	    ensure!(
117	        vocab_size == KIMI_K2_VOCAB,
118	        "vocab_size mismatch: {vocab_size}"
119	    );
120	    ensure!(
121	        num_hidden_layers == KIMI_K2_LAYERS,
122	        "num_hidden_layers mismatch: {num_hidden_layers}"
123	    );
124	    ensure!(
125	        first_k_dense_replace == KIMI_K2_DENSE_LAYERS,
126	        "first_k_dense_replace mismatch: {first_k_dense_replace}"
127	    );
128	    ensure!(
129	        max_position_embeddings == KIMI_K2_MAX_CONTEXT,
130	        "max_position_embeddings mismatch: {max_position_embeddings}"
131	    );
132	    ensure!(
133	        num_attention_heads == KIMI_K2_HEADS,
134	        "num_attention_heads mismatch: {num_attention_heads}"
135	    );
136	    ensure!(
137	        q_lora_rank == KIMI_K2_Q_LORA_RANK,
138	        "q_lora_rank mismatch: {q_lora_rank}"
139	    );
140	    ensure!(
141	        kv_lora_rank == KIMI_K2_KV_LORA_RANK,
142	        "kv_lora_rank mismatch: {kv_lora_rank}"
143	    );
144	    ensure!(
145	        qk_nope_head_dim == KIMI_K2_QK_NOPE_HEAD_DIM,
146	        "qk_nope_head_dim mismatch: {qk_nope_head_dim}"
147	    );
148	    ensure!(
149	        qk_rope_head_dim == KIMI_K2_QK_ROPE_HEAD_DIM,
150	        "qk_rope_head_dim mismatch: {qk_rope_head_dim}"
151	    );
152	    ensure!(
153	        v_head_dim == KIMI_K2_V_HEAD_DIM,
154	        "v_head_dim mismatch: {v_head_dim}"
155	    );
156	    ensure!(
157	        n_routed_experts == KIMI_K2_ROUTED_EXPERTS,
158	        "n_routed_experts mismatch: {n_routed_experts}"
159	    );
160	    ensure!(
161	        num_experts_per_tok == KIMI_K2_TOPK,
162	        "num_experts_per_tok mismatch: {num_experts_per_tok}"
163	    );
164	    ensure!(
165	        n_shared_experts == KIMI_K2_SHARED_EXPERTS,
166	        "n_shared_experts mismatch: {n_shared_experts}"
167	    );
168	    ensure!(
169	        moe_intermediate_size == KIMI_K2_EXPERT_INTERMEDIATE,
170	        "moe_intermediate_size mismatch: {moe_intermediate_size}"
171	    );
172	    ensure!(
173	        dense_intermediate_size == KIMI_K2_DENSE_INTERMEDIATE,
174	        "intermediate_size mismatch: {dense_intermediate_size}"
175	    );
176	    ensure!(
177	        (rms_norm_eps - f64::from(KIMI_K2_RMS_NORM_EPS)).abs() < 1.0e-12,
178	        "rms_norm_eps mismatch: {rms_norm_eps}"
179	    );
180	
181	    let rope_scaling = text
182	        .get("rope_scaling")
183	        .ok_or_else(|| anyhow::anyhow!("Kimi config missing rope_scaling"))?;
184	    let rope_scaling_type = rope_scaling
185	        .get("type")
186	        .and_then(Value::as_str)
187	        .map(ToOwned::to_owned);
188	    ensure!(
189	        rope_scaling_type.as_deref() == Some("yarn"),
190	        "Kimi rope_scaling.type must be yarn, got {:?}",
191	        rope_scaling_type
192	    );
193	    ensure_float_close(
194	        number_field(rope_scaling, "factor")?,
195	        f64::from(KIMI_K2_YARN_FACTOR),
196	        1.0e-6,
197	        "rope_scaling.factor",
198	    )?;
199	    ensure!(
200	        usize_field(rope_scaling, "original_max_position_embeddings")?
201	            == KIMI_K2_YARN_ORIGINAL_MAX_POS,
202	        "Kimi rope_scaling.original_max_position_embeddings mismatch"
203	    );
204	    ensure_float_close(
205	        number_field(rope_scaling, "beta_fast")?,
206	        f64::from(KIMI_K2_YARN_BETA_FAST),
207	        1.0e-6,
208	        "rope_scaling.beta_fast",
209	    )?;
210	    ensure_float_close(
211	        number_field(rope_scaling, "beta_slow")?,
212	        f64::from(KIMI_K2_YARN_BETA_SLOW),
213	        1.0e-6,
214	        "rope_scaling.beta_slow",
215	    )?;
216	    ensure_float_close(
217	        number_field(rope_scaling, "mscale")?,
218	        1.0,
219	        1.0e-12,
220	        "rope_scaling.mscale",
221	    )?;
222	    ensure_float_close(
223	        number_field(rope_scaling, "mscale_all_dim")?,
224	        1.0,
225	        1.0e-12,
226	        "rope_scaling.mscale_all_dim",
227	    )?;
228	
229	    let quantization_config = text.get("quantization_config");
230	    let quant_method = quantization_config
231	        .and_then(|value| value.get("quant_method"))
232	        .and_then(Value::as_str)
233	        .map(ToOwned::to_owned);
234	    let quant_format = quantization_config
235	        .and_then(|value| value.get("format"))
236	        .and_then(Value::as_str)
237	        .map(ToOwned::to_owned);
238	    ensure!(
239	        quant_method.as_deref() == Some("compressed-tensors"),
240	        "Kimi quantization_config.quant_method must be compressed-tensors, got {:?}",
241	        quant_method
242	    );
243	    ensure!(
244	        quant_format.as_deref() == Some("pack-quantized"),
245	        "Kimi quantization_config.format must be pack-quantized, got {:?}",
246	        quant_format
247	    );
248	
249	    Ok(())
250	}
251	
252	fn string_field(json: &Value, key: &str) -> Result<String> {
253	    json.get(key)
254	        .and_then(Value::as_str)
255	        .map(ToOwned::to_owned)
256	        .ok_or_else(|| anyhow::anyhow!("missing string field {key}"))
257	}
258	
259	fn usize_field(json: &Value, key: &str) -> Result<usize> {
260	    let value = json
261	        .get(key)
262	        .and_then(Value::as_u64)
263	        .ok_or_else(|| anyhow::anyhow!("missing unsigned integer field {key}"))?;
264	    usize::try_from(value).with_context(|| format!("field {key} does not fit usize"))
265	}
266	
267	fn bool_field(json: &Value, key: &str) -> Result<bool> {
268	    json.get(key)
269	        .and_then(Value::as_bool)
270	        .ok_or_else(|| anyhow::anyhow!("missing bool field {key}"))
271	}
272	
273	fn number_field(json: &Value, key: &str) -> Result<f64> {
274	    json.get(key)
275	        .and_then(Value::as_f64)
276	        .ok_or_else(|| anyhow::anyhow!("missing numeric field {key}"))
277	}
278	
279	fn ensure_float_close(actual: f64, expected: f64, tolerance: f64, label: &str) -> Result<()> {
280	    ensure!(
281	        (actual - expected).abs() <= tolerance,
282	        "{label} mismatch: got {actual}, expected {expected}"
283	    );
284	    Ok(())
285	}
