1	//! Kimi-K2's [`ModelLine`] implementation.
2	
3	use clap::Args as ClapArgs;
4	use clap::FromArgMatches;
5	use pegainfer_frontend::engine::EpBackend;
6	use pegainfer_frontend::engine::LaunchedEngine;
7	use pegainfer_frontend::model_line::LaunchContext;
8	use pegainfer_frontend::model_line::ModelLine;
9	
10	use crate::KimiLaunchOptions;
11	
12	pub static MODEL_LINE: KimiK2Line = KimiK2Line;
13	
14	pub struct KimiK2Line;
15	
16	// Kimi-K2-exclusive CLI flags.
17	#[derive(ClapArgs)]
18	struct KimiCli {
19	    /// Expert-parallel backend for Kimi-K2 (TP1/DP8 requires deepep; TP8/DP1 requires nccl)
20	    #[arg(long, default_value = "deepep")]
21	    ep_backend: CliEpBackend,
22	}
23	
24	#[derive(Clone, Copy, Debug, clap::ValueEnum)]
25	enum CliEpBackend {
26	    Nccl,
27	    #[value(name = "deepep")]
28	    DeepEp,
29	}
30	
31	impl From<CliEpBackend> for EpBackend {
32	    fn from(value: CliEpBackend) -> Self {
33	        match value {
34	            CliEpBackend::Nccl => Self::Nccl,
35	            CliEpBackend::DeepEp => Self::DeepEp,
36	        }
37	    }
38	}
39	
40	fn config_model_type(config: &serde_json::Value) -> Option<&str> {
41	    config.get("model_type").and_then(serde_json::Value::as_str)
42	}
43	
44	fn text_config_model_type(config: &serde_json::Value) -> Option<&str> {
45	    config
46	        .get("text_config")
47	        .and_then(|text| text.get("model_type"))
48	        .and_then(serde_json::Value::as_str)
49	}
50	
51	impl ModelLine for KimiK2Line {
52	    fn name(&self) -> &'static str {
53	        "Kimi-K2.6"
54	    }
55	
56	    fn probe(&self, config: &serde_json::Value) -> Result<(), String> {
57	        let is_kimi = matches!(config_model_type(config), Some("kimi_k25" | "kimi_k2"))
58	            || text_config_model_type(config) == Some("kimi_k2");
59	        if !is_kimi {
60	            return Err(format!(
61	                "model_type {:?} is not a Kimi-K2 identity",
62	                config_model_type(config)
63	            ));
64	        }
65	        crate::config::probe_config_json(config).map_err(|error| error.to_string())
66	    }
67	
68	    fn augment_cli(&self, cmd: clap::Command) -> clap::Command {
69	        KimiCli::augment_args(cmd)
70	    }
71	
72	    fn consumed_shared_args(&self) -> &'static [&'static str] {
73	        &["tp_size", "dp_size", "cuda_graph"]
74	    }
75	
76	    fn launch(&self, ctx: &LaunchContext<'_>) -> anyhow::Result<LaunchedEngine> {
77	        let cli =
78	            KimiCli::from_arg_matches(ctx.matches).expect("KimiCli parses from the merged command");
79	        crate::launch(
80	            ctx.model_path,
81	            KimiLaunchOptions {
82	                tp_size: ctx.shared.tp_size,
83	                dp_size: ctx.shared.dp_size.unwrap_or(8),
84	                ep_backend: cli.ep_backend.into(),
85	                cuda_graph: ctx.shared.cuda_graph,
86	            },
87	        )
88	        .map(LaunchedEngine::Handle)
89	    }
90	}
91	
92	#[cfg(test)]
93	mod tests {
94	    use super::*;
95	
96	    #[test]
97	    fn probe_rejects_foreign_model_type() {
98	        let config = serde_json::json!({"model_type": "qwen3"});
99	        let reason = MODEL_LINE.probe(&config).unwrap_err();
100	        assert!(reason.contains("Kimi-K2"), "{reason}");
