42	/// TP8 replicates the KV pool on every rank: 8192 pages × 16 tokens ×
43	/// (576 ckv + 64 kpe) bf16 ≈ 9.2 GiB per rank — the same footprint as the
44	/// old static bs64 arena, now shared across requests instead of sliced
45	/// into fixed 2048-token slots.
46	const KIMI_TP8_KV_POOL_PAGES: usize = 8192;
47	/// DP shards requests across ranks, so each rank only backs its own slots:
48	/// 1024 pages ≈ 1.15 GiB per rank (the old per-rank arena footprint).
49	const KIMI_DP_KV_POOL_PAGES_PER_RANK: usize = 1024;
50	
51	pub(crate) fn start_engine(model_path: &Path, options: &EngineLoadOptions) -> Result<EngineHandle> {
52	    let parallel = resolve_parallel_config(options);
53	    info!(
54	        "resolving engine startup: model_path={}, tp_size={}, dp_size={}, ep_size={}, ep_backend={:?}, devices={:?}",
55	        model_path.display(),
56	        parallel.tp_world(),
57	        parallel.dp_world(),
58	        parallel.ep_world(),
59	        options.ep_backend,
60	        options.device_ordinals
61	    );
62	    ensure!(
63	        options.device_ordinals.len() == parallel.ep_world(),
64	        "Kimi-K2 {:?} requires {} devices, got {:?}",
65	        parallel,
66	        parallel.ep_world(),
67	        options.device_ordinals
68	    );
69	
70	    match (parallel.tp_world(), parallel.dp_world()) {
71	        (8, 1) => start_engine_tp8_dp1(model_path, options, parallel),
72	        (1, 8) => start_engine_tp1_dp8(model_path, options, parallel),
73	        _ => bail!(
74	            "Kimi-K2 TP{}/DP{} not yet supported (v1: TP8DP1 or TP1DP8)",
75	            parallel.tp_world(),
76	            parallel.dp_world()
77	        ),
78	    }
79	}
