271	fn maybe_load_rank_weights(
272	    model_path: &Path,
273	    load_plans: &[KimiRankSlicedLoadPlan],
274	    workers: &[KimiRankWorker],
275	) -> Result<Vec<KimiRankWeightLoadReport>> {
276	    let started = Instant::now();
277	    info!("start load rank weights: ranks={}", workers.len());
278	    ensure_weight_payload_available(model_path, load_plans)?;
279	    let receivers = workers
280	        .iter()
281	        .map(|worker| worker.load_sliced_weights_async(model_path))
282	        .collect::<Result<Vec<_>>>()?;
283	    let mut reports = Vec::with_capacity(workers.len());
284	    for (worker, receiver) in workers.iter().zip(receivers) {
285	        let rank = worker.placement().rank;
286	        let report = receiver
287	            .recv()
288	            .map_err(|_| {
289	                anyhow::anyhow!(
290	                    "Kimi-K2 rank {} dropped weight load response",
291	                    worker.placement().rank
292	                )
293	            })?
294	            .with_context(|| {
295	                format!(
296	                    "Kimi-K2 rank {} sliced weight load failed",
297	                    worker.placement().rank
298	                )
299	            })?;
300	        debug!(
301	            "rank {rank} weights loaded: tensors={}, bytes={}, expert_layers={}",
302	            report.tensor_count,
303	            ByteSize(report.total_bytes as u64),
304	            report.expert_kernel_layers
305	        );
306	        reports.push(report);
307	    }
308	    info!(
309	        "load rank weights cost {:.2}s: ranks={}",
310	        started.elapsed().as_secs_f64(),
311	        reports.len()
312	    );
313	    Ok(reports)
