316	fn spawn_workers(config: &KimiK2RunnerConfig) -> Result<Vec<KimiRankWorker>> {
317	    let started = Instant::now();
318	    let n = config.placements.len();
319	    info!("start spawn rank workers: ranks={n}");
320	    ensure!(
321	        config.rank_weight_names.len() == n && config.rank_sliced_load_plans.len() == n,
322	        "Kimi-K2 names/sliced counts must match {} placements",
323	        n
324	    );
325	    let contexts = config
326	        .placements
327	        .iter()
328	        .map(|placement| KimiRankGpuContext::new(placement.device_ordinal))
329	        .collect::<Result<Vec<_>>>()?;
330	    let collective_barrier = Arc::new(Barrier::new(config.parallel.tp_world()));
331	    let mut workers = Vec::with_capacity(n);
332	    for (((&placement, weight_names), sliced_load_plan), ctx) in config
333	        .placements
334	        .iter()
335	        .zip(config.rank_weight_names.iter().cloned())
336	        .zip(config.rank_sliced_load_plans.iter().cloned())
337	        .zip(contexts)
338	    {
339	        let thread_placement = config.thread_placement.rank(placement.rank)?;
340	        let worker = KimiRankWorker::spawn(
341	            placement,
342	            weight_names,
343	            sliced_load_plan,
344	            thread_placement,
345	            config.local_dims,
346	            ctx,
347	            Arc::clone(&collective_barrier),
348	            config.enable_cuda_graph,
349	            config.kv_pool_pages,
350	        )?;
351	        debug_assert_eq!(worker.placement(), placement);
352	        workers.push(worker);
353	    }
354	    info!(
355	        "spawn rank workers cost {:.2}s: ranks={}",
356	        started.elapsed().as_secs_f64(),
357	        workers.len()
358	    );
359	    Ok(workers)
360	}
