336	        .zip(config.rank_sliced_load_plans.iter().cloned())
337	        .zip(contexts)
338	    {
339	        let thread_placement = config.thread_placement.rank(placement.rank)?;
340	        let worker = KimiRankWorker::spawn(
341	            placement,
342	            weight_names,
343	            sliced_load_plan,
344	            thread_placement,
345	            config.local_dims,
346	            ctx,
347	            Arc::clone(&collective_barrier),
348	            config.enable_cuda_graph,
349	            config.kv_pool_pages,
350	        )?;
351	        debug_assert_eq!(worker.placement(), placement);
352	        workers.push(worker);
353	    }
354	    info!(
355	        "spawn rank workers cost {:.2}s: ranks={}",
356	        started.elapsed().as_secs_f64(),
357	        workers.len()
358	    );
359	    Ok(workers)
360	}
361	
362	fn init_tp_nccl(workers: &[KimiRankWorker]) -> Result<()> {
363	    let started = Instant::now();
364	    info!("start TP NCCL init: ranks={}", workers.len());
365	    let nccl_id = cudarc::nccl::safe::Id::new()
366	        .map_err(|err| anyhow::anyhow!("Kimi TP NCCL unique id creation failed: {err:?}"))?;
367	    let comm_receivers = workers
368	        .iter()
369	        .map(|worker| worker.init_tp_comm_async(nccl_id, workers.len()))
370	        .collect::<Result<Vec<_>>>()?;
371	    for (rank, receiver) in comm_receivers.into_iter().enumerate() {
372	        receiver
373	            .recv()
374	            .map_err(|_| anyhow::anyhow!("Kimi rank {rank} dropped TP comm init response"))?
375	            .with_context(|| format!("Kimi rank {rank} TP comm init"))?;
376	    }
377	    info!(
378	        "TP NCCL init cost {:.2}s: ranks={}",
379	        started.elapsed().as_secs_f64(),
380	        workers.len()
381	    );
382	    Ok(())
383	}
384	
385	/// Collective DeepEP bootstrap: rank 0's unique id fans out to every rank
386	/// worker, which all enter the NCCL communicator + symmetric-window create
387	/// together. Send to all ranks before waiting on any response — each worker
388	/// blocks inside the collective until the last rank joins.
389	fn install_deepep_backends(workers: &[KimiRankWorker]) -> Result<()> {
390	    let started = Instant::now();
391	    info!("start install DeepEP EP backend: ranks={}", workers.len());
392	    let unique_id = pegainfer_kernels::ops::deepep_unique_id()?;
393	    let receivers = workers
394	        .iter()
395	        .map(|worker| worker.enable_deepep_async(unique_id, workers.len()))
396	        .collect::<Result<Vec<_>>>()?;
397	    for (rank, receiver) in receivers.into_iter().enumerate() {
398	        receiver
399	            .recv()
400	            .map_err(|_| anyhow::anyhow!("Kimi rank {rank} dropped DeepEP enable response"))?
401	            .with_context(|| format!("Kimi rank {rank} DeepEP enable"))?;
402	    }
403	    info!(
404	        "DeepEP EP backend install cost {:.2}s: ranks={}",
405	        started.elapsed().as_secs_f64(),
406	        workers.len()
407	    );
408	    Ok(())
409	}
410	
411	fn ensure_weight_payload_available(
412	    model_path: &Path,
413	    load_plans: &[KimiRankSlicedLoadPlan],
414	) -> Result<()> {
415	    let shards = load_plans
416	        .iter()
417	        .flat_map(|plan| plan.shards.iter().map(|shard| shard.shard.as_str()))
418	        .collect::<BTreeSet<_>>();
419	    let existing = shards
420	        .iter()
421	        .filter(|shard| model_path.join(shard).exists())
422	        .count();
423	    if existing != shards.len() {
424	        bail!(
425	            "Kimi-K2 weight payload under {} is incomplete: found {existing}/{} planned shards",
426	            model_path.display(),
427	            shards.len()
428	        );
429	    }
430	    Ok(())
431	}
