117	    pub(crate) fn new(rows: Vec<Vec<i32>>, padding_page: i32) -> Self {
118	        let mut pages = Vec::with_capacity(rows.iter().map(Vec::len).sum());
119	        let mut indptr = Vec::with_capacity(rows.len() + 1);
120	        indptr.push(0i32);
121	        for row in rows {
122	            pages.extend_from_slice(&row);
123	            indptr.push(pages.len() as i32);
