            KIMI_K2_RMS_NORM_EPS,
            &mut decode_arena.scratch.mla.normed,
        )?;
        match &layer.kind {
            KimiLayerForwardKindCache::Dense(dense) => {
                forward_dense_mlp_decode_normed_into(
                    device_ctx,
                    comm,
                    dense,
                    &mut decode_arena.scratch,
