7	
8	/// KV tokens a request can write over its lifetime. The final generated
9	/// token is returned but never fed back, so its KV is never written (the
10	/// same dangling-token contract as the qwen3 admission).
11	fn request_max_kv_tokens(req: &GenerateRequest) -> usize {
12	    req.prompt_tokens.len() + req.max_tokens.saturating_sub(1)
13	}
14	
15	/// Pool blocks a request may draw over its lifetime. One token more than
16	/// `request_max_kv_tokens`: kvbm appends the final generated token to the
17	/// sequence and provisions its block even though its KV is never written,
18	/// so at boundary alignments the peak draw is `ceil((prompt + max) / bs)`.
19	pub(in crate::runner) fn request_lifetime_blocks(
20	    req: &GenerateRequest,
21	    block_size: usize,
22	) -> usize {
23	    (req.prompt_tokens.len() + req.max_tokens)
24	        .div_ceil(block_size)
25	        .max(1)
26	}
27	
28	/// Honor-or-reject (#239): a request that can never fit — per-request KV
29	/// capacity, pool size, or a path-specific prompt cap — is rejected at
30	/// admission with the limit spelled out, instead of poisoning the batch
31	/// mid-decode when the KV write finally lands out of bounds.
32	pub(in crate::runner) fn validate_kv_capacity(
33	    req: &GenerateRequest,
34	    block_size: usize,
35	    max_request_blocks: usize,
36	    max_prompt_tokens: Option<usize>,
